  display: flex;
  align-items: center;
  gap: .5rem;
}
.avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  object-fit: cover;
  border: 1px solid #ddd;
}
.button {
  border: none;
  background: var(--accent);
  color: #161616;
  font-weight: 700;
  border-radius: 10px;
  padding: .75rem 1.1rem;
  cursor: pointer;
}
.button.secondary {
  background: #eceef7;
  color: #1b2340;
}
.load-wrap { text-align: center; margin-top: 1.2rem; }
.syllabus {
  display: grid;
  gap: .85rem;
