  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: .9rem 1rem;
  display: flex;
  align-items: center;
  gap: .85rem;
}
.syllabus-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: #e9edff;
  display: grid;
  place-items: center;
  font-weight: 800;
  color: #223078;
}
.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.1rem;
}
