  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: .6rem;
  margin: .8rem 0;
}
.amount-btn {
  border: 1px solid #d8dcef;
  background: #fff;
  border-radius: 10px;
  padding: .7rem .4rem;
  font-weight: 700;
  cursor: pointer;
}
.amount-btn.active {
  background: #fff3dd;
  border-color: #ffc465;
  color: #6d4400;
}
.faq-item {
  border-top: 1px solid var(--border);
  padding: .85rem 0;
}
.faq-q {
  width: 100%;
  background: transparent;
  border: 0;
  text-align: left;
  font-weight: 700;
  padding: .2rem 0;
  cursor: pointer;
  color: var(--text);
}
.faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height .28s ease;
  color: var(--muted);
}
.faq-item.open .faq-a { max-height: 160px; }
.tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: .65rem;
  margin: .5rem 0 1.2rem;
}
