  let rendered = 6;
  const renderCard = (article) => {
    const el = document.createElement('article');
    el.className = 'card';
    el.innerHTML = `
      <img class="thumb" src="${article.img}" alt="${article.title}">
      <div class="card-body">
        <span class="tag" style="background:${article.tagColor}">${article.tag}</span>
        <h3>${article.title}</h3>
