            <span>${article.author}</span>
          </div>
          <span>${article.time}</span>
        </div>
      </div>`;
    return el;
  };

  const appendChunk = () => {
    const next = articles.slice(rendered, rendered + 3);
    next.forEach((a) => homeGrid.appendChild(renderCard(a)));
